//! Keyboard Keycodes (SDL_keycode.h)

const std = @import("std");

const sdl = @import("../sdl3.zig");

/// The SDL virtual key representation.
///
/// Values of this type are used to represent keyboard keys using the current
/// layout of the keyboard. These values include Unicode values representing
/// the unmodified character that would be generated by pressing the key, or an
/// `Keycode` constant for those keys that do not generate characters.
///
/// A special exception is the number keys at the top of the keyboard which map
/// to `Keycode.@"0"`...`Keycode.@"9"` on AZERTY layouts.
///
/// Keys with the `Keycode.extended_mask` bit set do not map to a scancode or
/// unicode code point.
pub const Keycode = enum(u32) {
    pub const extended_mask: u32 = 1 << 29;
    pub const scancode_mask: u32 = 1 << 30;

    /// Get the keycode corresponding to a scancode that doesn't generate a
    /// character, see `scancodeToKeycode`.
    pub fn fromScancode(scancode: sdl.Scancode) Keycode {
        return @fromBackingInt(@intCast(scancodeToKeycode(scancode)));
    }

    unknown = 0,
    @"return" = '\r',
    escape = '\x1b',
    backspace = '\x08',
    tab = '\t',
    space = ' ',
    exclaim = '!',
    dblapostrophe = '"',
    hash = '#',
    percent = '%',
    dollar = '$',
    ampersand = '&',
    apostrophe = '\'',
    leftparen = '(',
    rightparen = ')',
