/// Transform an SDL scancode into an SDL keycode.
pub fn scancodeToKeycode(scancode: sdl.Scancode) u32 {
    return @backingInt(scancode) | Keycode.scancode_mask;
}

/// Valid key modifiers (possibly OR'd together).
pub const Keymod = packed struct(u16) {
    /// the left Shift key is down.
    lshift: bool = false,
    /// the right Shift key is down.
    rshift: bool = false,
    /// the Level 5 Shift key is down.
    level5: bool = false,
    __unused3: u3 = 0,
    /// the left Ctrl (Control) key is down.
    lctrl: bool = false,
    /// the right Ctrl (Control) key is down.
    rctrl: bool = false,
    /// the left Alt key is down.
    lalt: bool = false,
    /// the right Alt key is down.
    ralt: bool = false,
    /// the left GUI key (often the Windows key) is down.
    lgui: bool = false,
    /// the right GUI key (often the Windows key) is down.
    rgui: bool = false,
    /// the Num Lock key (may be located on an extended keypad) is down.
    num: bool = false,
    /// the Caps Lock key is down.
    caps: bool = false,
    /// the !AltGr key is down.
    mode: bool = false,
    /// the Scroll Lock key is down.
    scroll: bool = false,

    /// no modifier is applicable.
    pub const none: Keymod = .{};
    /// Any Ctrl key is down.
    pub const ctrl: Keymod = .{ .lctrl = true, .rctrl = true };
    /// Any Shift key is down.
    pub const shift: Keymod = .{ .lshift = true, .rshift = true };
    /// Any Alt key is down.
    pub const alt: Keymod = .{ .lalt = true, .ralt = true };
    /// Any GUI key is down.
    pub const gui: Keymod = .{ .lgui = true, .rgui = true };

    /// Whether either Ctrl key is down.
    pub fn hasCtrl(self: Keymod) bool {
        return self.lctrl or self.rctrl;
    }

    /// Whether either Shift key is down.
    pub fn hasShift(self: Keymod) bool {
        return self.lshift or self.rshift;
    }

    /// Whether either Alt key is down.
    pub fn hasAlt(self: Keymod) bool {
        return self.lalt or self.ralt;
    }

    /// Whether either GUI key is down.
    pub fn hasGui(self: Keymod) bool {
        return self.lgui or self.rgui;
    }
};

test "Keycode and Keymod" {
    try std.testing.expectEqual(Keycode.capslock, Keycode.fromScancode(.capslock));
    try std.testing.expectEqual(@as(u16, 0x00c0), @as(u16, @bitCast(Keymod.ctrl)));
    try std.testing.expectEqual(@as(u16, 0x8000), @as(u16, @bitCast(Keymod{ .scroll = true })));
    try std.testing.expect((Keymod{ .ralt = true }).hasAlt());
}
